-- 0005_add_org_programme — generated by `pnpm gen:migration`. Additive and reversible (ocs-db-migration);
-- never edit a migration once it is on main (CI pr-rules).
-- programme: the optional level 1a under a client (SOP-DEL-02 §3: "only when the client runs separate
-- programmes"). Staff see all; a client user sees its own client's programmes; partners see nothing.
CREATE TABLE programme (
  id          uuid PRIMARY KEY,
  client_id   uuid NOT NULL REFERENCES client (id),
  name        text NOT NULL,
  created_at  timestamptz NOT NULL DEFAULT now(),
  archived_at timestamptz,
  UNIQUE (client_id, name)
);
CREATE INDEX programme_client ON programme (client_id);

ALTER TABLE programme ENABLE ROW LEVEL SECURITY;
CREATE POLICY programme_internal ON programme FOR ALL TO ocs_app
  USING (app.is_internal()) WITH CHECK (app.is_internal());
CREATE POLICY programme_client_read ON programme FOR SELECT TO ocs_app
  USING (app.actor_kind() = 'client' AND client_id = ANY (app.client_ids()));
-- No DELETE: archive with archived_at (SOP-DEL-02 "never delete").
GRANT SELECT, INSERT, UPDATE ON programme TO ocs_app;

-- A site may belong to one programme of its own client (checked by org.site.create).
ALTER TABLE site ADD COLUMN programme_id uuid REFERENCES programme (id);
